extern "C" __device__
void dx_store_graph_fp32_tile(
        const float* source,
        float* destination,
        int destination_index,
        int triangular) {
    constexpr int shared_ld = 40;
    constexpr int global_ld = 512;
    const int row = threadIdx.x >> 3;
    const int col = (threadIdx.x & 7) * 4;
    #pragma unroll
    for (int store = 0; store < 2; ++store) {
        const int current_row = row + store * 16;
        const int shared_index = current_row * shared_ld + col;
        float* destination_global =
            destination + destination_index + current_row * global_ld + col;
        if (!triangular || current_row <= col) {
            *reinterpret_cast<float4*>(destination_global) =
                *reinterpret_cast<const float4*>(source + shared_index);
        } else if (current_row < col + 4) {
            #pragma unroll
            for (int lane = 0; lane < 4; ++lane) {
                if (current_row <= col + lane) {
                    destination_global[lane] = source[shared_index + lane];
                }
            }
        }
    }
}

