extern "C" __device__
void d256_cp_async_fp32_pair(
        float* first,
        float* second,
        const float* source,
        long long first_index,
        long long second_index) {
    constexpr int shared_ld = 68;
    constexpr int global_ld = 256;
    const int row = threadIdx.x >> 4;
    const int col = (threadIdx.x & 15) * 4;
    const unsigned first_base = static_cast<unsigned>(
        __cvta_generic_to_shared(first));
    const unsigned second_base = static_cast<unsigned>(
        __cvta_generic_to_shared(second));
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        const int current_row = row + load * 8;
        const int shared_index = current_row * shared_ld + col;
        const unsigned shared_offset =
            static_cast<unsigned>(shared_index * sizeof(float));
        const unsigned first_shared = first_base + shared_offset;
        const unsigned second_shared = second_base + shared_offset;
        const int global_offset = current_row * global_ld + col;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(first_shared),
               "l"(source + first_index + global_offset));
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
            :: "r"(second_shared),
               "l"(source + second_index + global_offset));
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void d256_cp_async_fp32_factor_half_panel(
